def test_parse_transcript_log_flags_and_field_whitespace():
    assert parse_transcript_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t"]) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": -2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


def test_parse_transcript_log_skips_blanks_and_comments():
    lines = ["", " \t\n", "#comment", " \t# not,a,record,at,all", "x#1,2,0"]
    assert parse_transcript_log(iter(lines)) == [{"id": "x#1", "day": 2, "flagged": False}]
    assert parse_transcript_log([]) == []


